from pycompss.api.task import task
from pycompss.api.api import compss_wait_on

@task(returns=float)
def compute_element(A_row, x):
    N = len(x)
    val = 0
    for j in range(N):
        val += A_row[j] * x[j]
    return val

def main(A, x):
    M = len(A)

    tasks = [compute_element(A[i], x) for i in range(M)]

    return compss_wait_on(tasks)
